# Generated by my-fsv completion install -- do not edit

_my_fsv_complete() {
    local cur prev words cword
    _init_completion 2>/dev/null || {
        COMPREPLY=(); cur=${COMP_WORDS[COMP_CWORD]}; prev=${COMP_WORDS[COMP_CWORD-1]}
        words=(${COMP_WORDS[@]}); cword=$COMP_CWORD
    }

    # Determine current subcommand path
    local cmd_path=''
    local i
    for ((i=1; i<cword; i++)); do
        case ${words[$i]} in
            -*) ;;
            *) cmd_path="${cmd_path:+$cmd_path }${words[$i]}" ;;
        esac
    done

    case "$cmd_path" in
        "changes list")
            case "$prev" in
                --where)
                    COMPREPLY=( $(FSV_THIN_COMPLETE=1 /opt/fsv/bin/fsv _complete bash complete_where changes "$cur") ); return 0 ;;
                -w)
                    COMPREPLY=( $(FSV_THIN_COMPLETE=1 /opt/fsv/bin/fsv _complete bash complete_where changes "$cur") ); return 0 ;;
                --kind)
                    COMPREPLY=( $(FSV_THIN_COMPLETE=1 /opt/fsv/bin/fsv _complete bash complete_lookup_query changes "$cur" -- "${COMP_WORDS[@]}") ); return 0 ;;
                -k)
                    COMPREPLY=( $(FSV_THIN_COMPLETE=1 /opt/fsv/bin/fsv _complete bash complete_lookup_query changes "$cur" -- "${COMP_WORDS[@]}") ); return 0 ;;
            esac
            COMPREPLY=( $(compgen -W "--verbose -v --where -w --kind -k --limit --yes -y" -- "$cur") )
            return 0 ;;
        "changes show")
            COMPREPLY=( $(compgen -W "--verbose -v" -- "$cur") )
            return 0 ;;
        "config set")
            case "$prev" in
                --key)
                    COMPREPLY=( $(compgen -W "completion.network" -- "$cur") ); return 0 ;;
                --value)
                    COMPREPLY=( $(compgen -W "on off true false 1 0" -- "$cur") ); return 0 ;;
                --group)
                    COMPREPLY=( $(FSV_THIN_COMPLETE=1 /opt/fsv/bin/fsv _complete bash complete_update_group_id - "$cur") ); return 0 ;;
            esac
            COMPREPLY=( $(compgen -W "--verbose -v --key --value --group" -- "$cur") )
            return 0 ;;
        "whoami")
            case "$prev" in
                --store)
                    COMPREPLY=( $(compgen -W "file argon keychain" -- "$cur") ); return 0 ;;
            esac
            COMPREPLY=( $(compgen -W "--verbose -v --store" -- "$cur") )
            return 0 ;;
        "changes")
            COMPREPLY=( $(compgen -W "list show --verbose -v --debug" -- "$cur") )
            return 0 ;;
        "config")
            COMPREPLY=( $(compgen -W "set --verbose -v" -- "$cur") )
            return 0 ;;
        "")
            case "$prev" in
                --format)
                    COMPREPLY=( $(compgen -W "table json csv tsv" -- "$cur") ); return 0 ;;
                -f)
                    COMPREPLY=( $(compgen -W "table json csv tsv" -- "$cur") ); return 0 ;;
            esac
            COMPREPLY=( $(compgen -W "whoami changes config --verbose -v --format -f" -- "$cur") )
            return 0 ;;
    esac
}

complete -F _my_fsv_complete my-fsv
